'use strict';const $=s=>document.querySelector(s);let busy=false,request=0;
function clear(){request++;$('#verify-result').hidden=true;$('#verify-counts').replaceChildren();$('#verify-format').textContent='';$('#verify-legacy').hidden=true;$('#verify-name').textContent='';$('#verify-time').textContent='';$('#verify-total').textContent='';}
function controls(){for(const id of ['verify-file','verify-checksum-file','verify-hash','verify-submit'])$('#'+id).disabled=busy;}
function status(text){$('#verify-status').textContent=text;}
$('#verify-form').addEventListener('submit',async event=>{event.preventDefault();if(busy)return;clear();const mine=++request;if(!KashierData.loggedIn()){location.replace('auth.html?next=verify-export.html');return;}const selected=$('#verify-file').files?.[0],hash=$('#verify-hash').value.trim();if(!selected){status('فایلێکی داتای پاشەکەوت هەڵبژێرە.');return;}if(!/^[0-9a-f]{64}$/i.test(hash)){status('کۆدی پەنجەمۆری فایلی سەرەتا بە ٦٤ پیت یان ژمارە بنووسە.');return;}if(!Number.isSafeInteger(selected.size)||selected.size<1||selected.size>25*1024*1024){status('زۆرترین قەبارەی فایل ٢٥ مێبی‌بایتە.');return;}busy=true;controls();status('خوێندنەوە و پشکنینی فایل…');try{const owner=KashierData.userId(),buffer=await selected.arrayBuffer(),result=await ExportFile.verify(buffer,owner,hash);if(mine!==request)return;if(!KashierData.loggedIn()||KashierData.userId()!==owner)throw Error('هەژمارەکە گۆڕاوە؛ دووبارە پشکنین بکە.');$('#verify-name').textContent=selected.name;$('#verify-time').textContent=new Intl.DateTimeFormat('ckb-IQ-u-ca-gregory-nu-latn',{timeZone:'Asia/Baghdad',dateStyle:'short',timeStyle:'medium'}).format(new Date(result.generatedAt));$('#verify-format').textContent='وەشانی پاشەکەوت: '+result.version;$('#verify-legacy').hidden=result.version>=8;$('#verify-total').textContent=new Intl.NumberFormat('en-US').format(result.total);for(const [key,label] of Object.entries(result.tableNames)){const row=document.createElement('tr'),name=document.createElement('td'),count=document.createElement('td');name.textContent=label;count.textContent=new Intl.NumberFormat('en-US').format(result.counts[key]);row.append(name,count);$('#verify-counts').append(row);}$('#verify-result').hidden=false;status('پشکنین تەواو بوو؛ فایلەکە لەگەڵ کۆدی پێدراو یەک دەگرێتەوە.');}catch(error){if(mine===request){clear();status((globalThis.KashierLocale?.message(error.message)??error.message));}}finally{busy=false;controls();}});
$('#verify-checksum-file').addEventListener('change',async()=>{if(busy)return;clear();const mine=request,owner=KashierData.userId();$('#verify-hash').value='';if(!KashierData.loggedIn()){status('سەرەتا بچۆ ژوورەوە.');return;}const selected=$('#verify-checksum-file').files?.[0];if(!selected){status('کۆدی پارێزراو بنووسە یان فایلەکەی هەڵبژێرە.');return;}busy=true;controls();try{const hash=await ExportFile.readChecksum(selected);if(mine!==request)return;if(!KashierData.loggedIn()||KashierData.userId()!==owner)throw Error('هەژمارەکە گۆڕاوە؛ دووبارە پشکنین بکە.');$('#verify-hash').value=hash;status('کۆدی فایل خوێندرایەوە؛ ئێستا فایلی داتای پاشەکەوت هەڵبژێرە و پشکنینی بکە.');}catch(e){if(mine===request)status((globalThis.KashierLocale?.message(e.message)??e.message));}finally{busy=false;controls();}});
for(const [id,event] of [['verify-file','change'],['verify-hash','input']])$('#'+id).addEventListener(event,()=>{clear();status('بۆ فایل یان کۆدی نوێ دووبارە پشکنین بکە.');});
const savedHash=new URLSearchParams(location.hash.slice(1)).get('sha256');if(savedHash&&/^[0-9a-f]{64}$/i.test(savedHash))$('#verify-hash').value=savedHash;
if(!KashierData.loggedIn())location.replace('auth.html?next=verify-export.html');

window.addEventListener('pagehide',()=>{clear();$('#verify-file').value='';$('#verify-checksum-file').value='';$('#verify-hash').value='';status('');});window.addEventListener('pageshow',e=>{if(e.persisted)location.reload();});
